SELECT COUNT(*) FROM (
    SELECT a.artregistry, a.artname,
        ROUND(CAST(
            (CASE sd.envsensitivity WHEN 'Low' THEN 1 WHEN 'Medium' THEN 5 WHEN 'High' THEN 10 END +
             CASE sd.lightsensitivity WHEN 'Low' THEN 1 WHEN 'Medium' THEN 5 WHEN 'High' THEN 10 END
            ) / 2.0 AS numeric), 2) AS risk_score
    FROM artifactscore a
    JOIN sensitivitydata sd ON a.artregistry = sd.artref
    WHERE ((CASE sd.envsensitivity WHEN 'Low' THEN 1 WHEN 'Medium' THEN 5 WHEN 'High' THEN 10 END +
             CASE sd.lightsensitivity WHEN 'Low' THEN 1 WHEN 'Medium' THEN 5 WHEN 'High' THEN 10 END
            ) / 2.0) > 7
) sub;

