SELECT COUNT(*) FROM (
    SELECT a.artregistry, a.artname, ra.conservepriorityscore AS risk_score
    FROM artifactscore a
    JOIN riskassessments ra ON a.artregistry = ra.artrefconcerned
    WHERE ra.conservepriorityscore > 7
) sub;

